"use client"

import * as React from "react"
import { ChevronLeft, ChevronRight } from "lucide-react"
import { cn } from "@/lib/utils"

function getPageList(page: number, pageCount: number): (number | "ellipsis")[] {
  const pages: (number | "ellipsis")[] = []
  const add = (p: number | "ellipsis") => pages.push(p)

  add(1)
  if (page > 3) add("ellipsis")
  for (let p = Math.max(2, page - 1); p <= Math.min(pageCount - 1, page + 1); p++) add(p)
  if (page < pageCount - 2) add("ellipsis")
  if (pageCount > 1) add(pageCount)

  return pages
}

type PaginationProps = {
  page: number
  pageCount: number
  onPageChange: (page: number) => void
  className?: string
}

// Matches the Figma Pagination component: bordered pill container, Prev/Next
// text+chevron buttons, numbered pages with the current page in --primary.
// Below sm the Prev/Next labels are screen-reader only, so the row fits 320 px.
function Pagination({ page, pageCount, onPageChange, className }: PaginationProps) {
  const pages = getPageList(page, pageCount)

  return (
    <nav
      aria-label="Pagination"
      data-slot="pagination"
      className={cn("flex items-center gap-1", className)}
    >
      <button
        type="button"
        onClick={() => onPageChange(page - 1)}
        disabled={page <= 1}
        className="flex h-(--control-md) items-center gap-1 rounded-md border border-border bg-card px-3 text-sm font-medium text-text-secondary transition-colors duration-fast ease-entrance hover:bg-muted/50 disabled:pointer-events-none disabled:opacity-40"
      >
        <ChevronLeft className="size-4" />
        <span className="sr-only sm:not-sr-only">Prev</span>
      </button>

      <div className="flex items-center gap-1">
        {pages.map((p, i) =>
          p === "ellipsis" ? (
            <span key={`ellipsis-${i}`} className="px-2 text-sm text-text-tertiary">
              …
            </span>
          ) : (
            <button
              key={p}
              type="button"
              aria-current={p === page ? "page" : undefined}
              onClick={() => onPageChange(p)}
              className={cn(
                "flex h-(--control-md) min-w-(--control-md) items-center justify-center rounded-md px-1 text-[13px] font-medium tabular-nums transition-colors duration-base ease-entrance",
                p === page
                  ? "bg-primary text-primary-foreground"
                  : "text-text-secondary hover:bg-muted/50"
              )}
            >
              {p}
            </button>
          )
        )}
      </div>

      <button
        type="button"
        onClick={() => onPageChange(page + 1)}
        disabled={page >= pageCount}
        className="flex h-(--control-md) items-center gap-1 rounded-md border border-border bg-card px-3 text-sm font-medium text-text-secondary transition-colors duration-fast ease-entrance hover:bg-muted/50 disabled:pointer-events-none disabled:opacity-40"
      >
        <span className="sr-only sm:not-sr-only">Next</span>
        <ChevronRight className="size-4" />
      </button>
    </nav>
  )
}

type PaginationSimpleProps = {
  page: number
  pageCount: number
  onPageChange: (page: number) => void
  className?: string
}

// The Figma variant with no page numbers — just Prev/Next and a "Page X of Y" label.
function PaginationSimple({ page, pageCount, onPageChange, className }: PaginationSimpleProps) {
  return (
    <nav
      aria-label="Pagination"
      data-slot="pagination-simple"
      className={cn("flex items-center justify-between gap-4", className)}
    >
      <button
        type="button"
        onClick={() => onPageChange(page - 1)}
        disabled={page <= 1}
        className="flex h-(--control-md) items-center gap-2 rounded-md border border-border bg-card px-3.5 text-sm font-medium text-foreground transition-colors duration-fast ease-entrance hover:bg-muted/50 disabled:pointer-events-none disabled:opacity-40"
      >
        <ChevronLeft className="size-4" />
        Previous
      </button>
      <span className="text-sm text-text-tertiary">
        Page {page} of {pageCount}
      </span>
      <button
        type="button"
        onClick={() => onPageChange(page + 1)}
        disabled={page >= pageCount}
        className="flex h-(--control-md) items-center gap-2 rounded-md border border-border bg-card px-3.5 text-sm font-medium text-foreground transition-colors duration-fast ease-entrance hover:bg-muted/50 disabled:pointer-events-none disabled:opacity-40"
      >
        Next
        <ChevronRight className="size-4" />
      </button>
    </nav>
  )
}

export { Pagination, PaginationSimple }

import type { CnFunction } from "cn"
import { createCn } from "cn/config"

/**
 * clsx + tailwind-merge, taught WunderUI's own theme utilities so they merge
 * in the right group: `text-label-sm` is a font size (not a text colour, which
 * dropped it next to `text-text-tertiary`), `bg-gradient-*` a background image
 * (not a colour that `bg-card` would remove), and the motion utilities
 * `ease-entrance …` and `duration-fast …` replace each other.
 */
export const cn: CnFunction = createCn({
  extend: {
    classGroups: {
      "font-size": [{ text: ["label-sm"] }],
      "bg-image": [
        {
          bg: [
            "gradient-primary",
            "gradient-indigo",
            "gradient-blue",
            "gradient-purple",
            "gradient-pink",
            "gradient-red",
            "gradient-orange",
            "gradient-yellow",
            "gradient-green",
            "gradient-alternative",
            "gradient-slate",
            "gradient-dark",
          ],
        },
      ],
      ease: [{ ease: ["entrance", "exit", "move", "overshoot", "spring"] }],
      duration: [{ duration: ["instant", "fast", "base", "slow", "deliberate", "ambient"] }],
    },
  },
})
